package mcp

// The tools/list entries of the agent tools, as src/mcp.ts's JSON.stringify writes them (generated by testdata/genlistings.mjs; mcp_test.go compares).
var agentListings = map[string]string{
	"workspace_share": "{\"name\":\"workspace_share\",\"group\":\"agents\",\"description\":\"Share your personal workspace folder with another agent on this machine. access: 'read' or 'write', or 'none' to stop sharing. The grantee gets a notice now. A revoke ('none') ends a Claude Code grant, or a Codex 'write' grant, at the grantee's next launch; other grants were never sandbox-enforced, so the grantee must stop using the folder. The grantee sees the folder in its \\\"Your workspace\\\" prompt block, and a Claude Code agent gets it as an allowed directory at its next launch (a Codex agent gets 'write' as a writable root). 'read' is advisory: every agent runs as the same Unix user, so stam can't stop a write. You need a personal workspace (spawned with `workspace`). Archiving you keeps the shares; archiving the grantee drops them.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"agent\":{\"type\":\"string\",\"description\":\"The agent to share with: id or name.\"},\"access\":{\"type\":\"string\",\"enum\":[\"read\",\"write\",\"none\"]}},\"required\":[\"agent\",\"access\"]}}",
	"find_agents":     "{\"name\":\"find_agents\",\"group\":\"registry\",\"description\":\"Search the stam registry by id, name, or role text. Without a query, lists the live agents you may see (active, paused and shut-down ones; archived ones are left out). With a query, archived agents are left out too, unless the query is exactly an agent's id or name. `state` overrides this: \\\"archived\\\" lists only archived agents, \\\"all\\\" lists every match. `role` keeps only agents whose role or name contains the text (case-insensitive); standing specialists come first, marked standing with their workspace name. Each agent carries its type: the saved type it was spawned as, or null.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"query\":{\"type\":\"string\"},\"role\":{\"type\":\"string\",\"description\":\"Specialty to find, matched against role and name as a case-insensitive substring.\"},\"state\":{\"type\":\"string\",\"enum\":[\"active\",\"archived\",\"all\"],\"description\":\"Which agents to list: active (not archived), archived, or all. Without it: live agents, plus an archived one only on an exact id or name match of the query.\"}}}}",
	"registry_info":   "{\"name\":\"registry_info\",\"group\":\"registry\",\"description\":\"Agent types (saved roles such as developer, reviewer, and manager, with when to use each; spawn one with spawn_agent type), harnesses, known models with their inputs (text, image, video), presets with when to use each, and the rule for missing capabilities.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{}}}",
	"spawn_agent":     "{\"name\":\"spawn_agent\",\"group\":\"agents\",\"description\":\"Start a new agent as your child: it is registered under you, you get its status and blockers, and you can control it with agent_control. Any model name works, even one stam does not know yet. The executive assistant can also start it under any parent or none, or as chief of staff. A developer spawn when the machine already runs developerCap developers (settings, default 6) is not refused but queued: you get \\\"queued, place N\\\" with the holders, the agent starts by itself when a slot frees (first come first served), and you get a notice when it does or fails. Keep working meanwhile; do not spawn it again. Reviewers and other types are never queued. To let the child comment on or join an ITSA without owning it, pass participate with its ids or keys; the spawn is refused before anything starts if you may not add participants to one.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"name\":{\"type\":\"string\",\"description\":\"Unique lowercase name with dashes.\"},\"role\":{\"type\":\"string\",\"description\":\"What it is for. Defaults to its type.\"},\"prompt\":{\"type\":\"string\",\"description\":\"Its first task. With a type that has a brief, this is the brief's {{task}}.\"},\"type\":{\"type\":\"string\",\"description\":\"An agent type from registry_info, such as \\\"developer\\\", \\\"reviewer\\\", or \\\"manager\\\": sets its harness, model, effort, role, standing instructions, brief, and worktree default. Explicit fields override it. A reviewer type follows its fallback chain when its account is held. A ring reviewer type (no harness, model, or preset allowed) starts a ring named NAME: members NAME-1, NAME-2, ... and a moderator NAME-mod, with your prompt as the topic; its result is mailed to you, and if a member can't start, the type's fallback runs as a single reviewer.\"},\"brief_vars\":{\"type\":\"object\",\"additionalProperties\":{\"type\":\"string\"},\"description\":\"Extra values for placeholders in the type's brief.\"},\"preset\":{\"type\":\"string\",\"description\":\"A preset from registry_info, such as \\\"fast\\\" or \\\"deep\\\". Sets harness, model, and effort.\"},\"harness\":{\"type\":\"string\",\"description\":\"\\\"claude\\\" (default), \\\"opencode\\\", or \\\"codex\\\".\"},\"model\":{\"type\":\"string\"},\"effort\":{\"type\":\"string\"},\"cwd\":{\"type\":\"string\",\"description\":\"Directory to work in, or the repo for a worktree. Defaults to yours.\"},\"machine\":{\"type\":\"string\",\"description\":\"Machine to run it on, from the machine field in find_agents. Defaults to yours.\"},\"worktree\":{\"type\":\"boolean\",\"description\":\"Give it its own git worktree and branch, removed when it is archived. Defaults to the type's worktree default (the developer type is true). A developer that ends up without one in the live deploy checkout is refused, since its commits there would hold every deploy.\"},\"base\":{\"type\":\"string\",\"description\":\"A git ref to cut the worktree's branch from, such as origin/stam/x (fetched first; a local branch works too). The spawn fails if it does not resolve. Without it, a repo with an origin remote is cut from a freshly fetched origin/main (falling back to the checkout's HEAD if the fetch fails; the spawn's workspace:base event says which). A base of origin/stam/X (or storage/stam/X) continues that PR: the worktree goes on stam/X itself at the base's commit, so pr_open updates the PR with no fast-forward (the spawn result and the workspace:base event say so). The spawn is refused when stam/X is checked out in another worktree (archive its holder) or a local stam/X has commits the base lacks. To stack a NEW PR on stam/X instead, pass branch: \\\"new\\\" (a reviewer type always gets its own branch). Only with a worktree.\"},\"branch\":{\"type\":\"string\",\"description\":\"The worktree's branch name. Defaults to stam/NAME, or to the PR branch itself when base is origin/stam/X. Pass a new name, or \\\"new\\\" for stam/NAME, to cut a new branch (a stacked PR) from that base instead of continuing it. An explicit name is used as given. When the default stam/NAME is already taken (here or on origin), the branch gets a free -2, -3 suffix; the spawn result and the agent's brief name it. Only with a worktree.\"},\"workspace_script\":{\"type\":\"string\",\"description\":\"Shell command that prints the directory to work in.\"},\"workspace_instructions\":{\"type\":\"string\",\"description\":\"Tell it to create its own workspace this way.\"},\"standing\":{\"type\":\"boolean\",\"description\":\"A long-lived specialist, kept as a standing agent rather than one for a single task. A standing agent idle for standing.idleHours (default 4) rests, harness stopped, and mail, a fired wake_me or an assigned ITSA wakes it.\"},\"workspace\":{\"type\":[\"boolean\",\"string\"],\"description\":\"A personal workspace folder for this agent, at STAM_HOME/workspaces/NAME, separate from its working directory and kept when it is archived. true uses the agent's own name; a string names a workspace (lowercase letters, digits, and dashes), so a respawned specialist can adopt an archived one's folder. Never a git repo or worktree.\"},\"visibility\":{\"type\":\"object\",\"description\":\"Whom the child may reach. reach: \\\"all\\\" (default), \\\"tree\\\", or \\\"parent\\\"; siblings: may it mail its siblings; registry: may it see the whole registry.\",\"properties\":{\"reach\":{\"type\":\"string\",\"enum\":[\"all\",\"tree\",\"parent\"]},\"siblings\":{\"type\":\"boolean\"},\"registry\":{\"type\":\"boolean\"}}},\"child_notices\":{\"type\":\"string\",\"enum\":[\"turn\",\"tree-idle\",\"none\"],\"description\":\"How much this child hears about its own children's finished turns: 'tree-idle' (default), 'turn', or 'none'. Blocked and errored agents always reach their parents.\"},\"urgent\":{\"type\":\"string\",\"enum\":[\"red-main\",\"deploy-hold\",\"approved-pr\",\"incident\"],\"description\":\"Only for a developer spawn that has to queue because the slots are full: the reason it should go ahead of normal spawns (first come first served within each class). red-main: a fix for a red main; deploy-hold: a fix that clears a deploy hold; approved-pr: a fix on an approved PR; incident: a fix for an incident, which goes ahead like red-main only when its itsa (or one of that ITSA's parents) is marked an incident by the chief of staff or the human (itsa_set incident=true), and is refused otherwise. On another machine the ITSA home is asked for the mark, and the spawn is refused unless it says yes. Not for anything else.\"},\"itsa\":{\"type\":\"string\",\"description\":\"An ITSA id or key: the new agent becomes its owner (a reviewer type joins as a participant instead, and the owner stays), and its first prompt carries the ITSA (key, title, summary, body, parent chain, links). With no prompt, that block is the prompt.\"},\"participate\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"ITSA ids or keys the new agent joins as a participant, without owning them: it can comment and change them, and the owner stays. You must be allowed to add participants to each (an owner, a participant, or an owner of a parent ITSA). If you are not, the spawn is refused and nothing starts.\"},\"parent\":{\"type\":\"string\",\"description\":\"Executive assistant only: the parent agent, or \\\"none\\\" for a top-level agent. Defaults to you.\"},\"chief_of_staff\":{\"type\":\"boolean\",\"description\":\"Executive assistant only: make it the chief of staff.\"}},\"required\":[\"name\"]}}",
	"agent_control":   "{\"name\":\"agent_control\",\"group\":\"agents\",\"description\":\"Control yourself or one of your children: pause, unpause, shutdown, archive (shut down and remove its worktree), resume, restart, reconnect-mcp, set-visibility, set-child-notices (how much you hear about your children's finished turns: \\\"turn\\\", \\\"tree-idle\\\", or \\\"none\\\"; blocked and errored children always reach you). cancel removes a developer spawn that is still queued for a slot, by its name in agent (not an agent yet, so no agent id): its caller, the caller's parents, and the chief of staff may cancel it; a spawn already granted a slot is refused, and a name that isn't queued is a 404. Cancel finds the spawn on whichever machine queued it and forwards to that machine; there, the caller's parents can cancel only when that machine knows the caller (otherwise only the caller and the chief of staff can), and an unreachable machine gives a 502, not a 404. The chief of staff can also adopt any agent as its parent. Shutdown, archive, and restart wait until the agent finishes its current step. Every archive asks the agent for its final retro round and waits for its next turn end, bounded by settings.archive.finalRoundMinutes (default 3); a wrap-up pushed while the agent runs a step can get one more turn, with a fresh finalRoundMinutes deadline, because the harness may hold it for the next turn; archive with force only skips the turn-alive check for an agent whose harness is gone, and archive with discard removes uncommitted worktree changes. The executive assistant controls every agent, and alone can also set-parent (parent: an agent, or \\\"none\\\" for top-level), rename (name), make one chief-of-staff, kill (stop now), and forget (remove a stopped agent from the registry).\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"agent\":{\"type\":\"string\",\"description\":\"Id or name of the agent.\"},\"action\":{\"type\":\"string\",\"enum\":[\"pause\",\"unpause\",\"shutdown\",\"archive\",\"resume\",\"restart\",\"reconnect-mcp\",\"adopt\",\"set-visibility\",\"set-child-notices\",\"set-parent\",\"rename\",\"chief-of-staff\",\"kill\",\"forget\",\"cancel\"]},\"note\":{\"type\":\"string\",\"description\":\"For resume and restart: a note the agent receives.\"},\"force\":{\"type\":\"boolean\",\"description\":\"For archive: do not wait for the agent's current step. A forced pending archive whose harness is gone runs at once, skipping the turn-alive check; it still asks the agent for its final round, bounded by settings.archive.finalRoundMinutes, and a forced archive of a live agent waits for that extra turn too. It also discards uncommitted worktree changes. For unpause: clear its cost blockers too.\"},\"force_unpushed\":{\"type\":\"boolean\",\"description\":\"For archive: archive although the branch has commits that are on no remote (the archive is refused otherwise, naming the branch, the count and the head; push it or pr_open first). The commits stay on the local branch, which the archive keeps.\"},\"discard\":{\"type\":\"boolean\",\"description\":\"For archive: discard the agent's uncommitted worktree changes. Every archive asks the agent for its final retro round and waits for its next turn end, at most settings.archive.finalRoundMinutes (default 3), before archiving.\"},\"visibility\":{\"type\":\"object\",\"description\":\"For set-visibility: same shape as in spawn_agent.\"},\"child_notices\":{\"type\":\"string\",\"enum\":[\"turn\",\"tree-idle\",\"none\"],\"description\":\"For set-child-notices: how much you hear about your children's finished turns.\"},\"parent\":{\"type\":\"string\",\"description\":\"For set-parent: the new parent, or \\\"none\\\".\"},\"name\":{\"type\":\"string\",\"description\":\"For rename: the new name.\"}},\"required\":[\"agent\",\"action\"]}}",
	"compact_self":    "{\"name\":\"compact_self\",\"group\":\"agents\",\"description\":\"Compact your own conversation when you end your current turn. Say what the summary must keep, and give a prompt you will receive right after compaction so you can continue.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"instructions\":{\"type\":\"string\",\"description\":\"What the summary must keep.\"},\"prompt_after\":{\"type\":\"string\",\"description\":\"The prompt you receive after compaction.\"}},\"required\":[\"instructions\",\"prompt_after\"]}}",
	"reconnect_mcp":   "{\"name\":\"reconnect_mcp\",\"group\":\"agents\",\"description\":\"Reconnect your own MCP servers. In some harnesses this restarts you and resumes your conversation after your current step.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"}}}}",
}
